  public static void Apply(Control root){
   root.Text=T(root.Text);var grid=root as DataGridView;if(grid!=null)foreach(DataGridViewColumn col in grid.Columns)col.HeaderText=T(col.HeaderText);
   var strip=root as ToolStrip;if(strip!=null)foreach(ToolStripItem item in strip.Items)ApplyItem(item);
   foreach(Control c in root.Controls)Apply(c);
  }
  private static void ApplyItem(ToolStripItem item){item.Text=T(item.Text);item.ToolTipText=T(item.ToolTipText);var dd=item as ToolStripDropDownItem;if(dd!=null)foreach(ToolStripItem c in dd.DropDownItems)ApplyItem(c);}
  public static void TranslateCombo(ComboBox c){c.FormattingEnabled=true;c.Format+=(s,e)=>e.Value=T(Convert.ToString(e.ListItem));}
